import impl

# ---- visible cases -------------------------------------------------------
def test_example_1():
    assert impl.solve("Device is scanning all ports on the subnet with no user logged in") == "worm"


def test_example_2():
    assert impl.solve("All .docx files have been encrypted; a ransom note appeared on the desktop") == "ransomware"


def test_example_3():
    assert impl.solve("A free game installer is sending keystrokes to a remote server") == "trojan"


def test_example_4():
    assert impl.solve("An email attachment infected the file and spread copies to shared folders") == "virus"


def test_example_5():
    assert impl.solve("Battery usage is higher than usual after a long meeting") == "unknown"


# ---- hidden / edge cases -------------------------------------------------
def test_edge_empty():
    assert impl.solve("") == "unknown"


def test_case_insensitive():
    assert impl.solve("SCANNING FOR VULNERABILITIES") == "worm"
    assert impl.solve("bitcoin demand") == "ransomware"


def test_priority():
    # contains "scanning" (worm) and "host file" (virus). Should return "worm" due to priority.
    assert impl.solve("scanning infected host file") == "worm"
    # contains "encrypt" (ransomware) and "backdoor" (trojan). Should return "ransomware".
    assert impl.solve("encrypt files backdoor access") == "ransomware"
